//! 🏗️ One real header birth and every cached cut preserve original identity, cancellation and paid close.
use semio_framework_job::*;
use semio_framework_value_testing_allocator as _;
use semio_framework_job_payload::{RetainedPayloadBuilder,JobPayloadStream};
fn clock()->Option<u64>{Some(1000)}
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);assert!(!heap.overflowed);(value,(heap.requested_bytes,heap.released_bytes))}
fn exact(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth.max(1)}}
#[test]
fn original_empty_payload_header_initialization_preserves_every_scalar_and_final_header_prefix(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let row=&fixture["initialization"];let turns=row["turns"].as_u64().unwrap()as usize;let bound=row["maximumTurns"].as_u64().unwrap()as usize;let stock=RetainedCloneGrant{maximum_items:10_000,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:64};assert_eq!(JOB_PAYLOAD_OPERATION_PAGES,row["maximumPages"].as_u64().unwrap()as usize);
 for cut in 0..=bound{
  let mut caller=OriginalJobFixtureCaller::admit(OperationId(99209),Generation(17),stock,clock,1000000,10000);let birth=(caller.born_bytes(),0);let mut storage=std::mem::MaybeUninit::<RetainedPayloadBuilder>::uninit();let metadata=RetainedPayloadBuilder::empty_carrier_copy_bytes();
  caller.turn(RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:metadata,..stock},|cx|{cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:metadata,..Default::default()})?;unsafe{RetainedPayloadBuilder::initialize_empty_at(storage.as_mut_ptr(),JobPayloadStream::Preview)}cx.consume_fuel(1);Ok(())}).unwrap();let builder=unsafe{storage.assume_init_mut()};let identity=builder.native_header_identity();
  for turn in 0..cut{
   let demand=builder.initialization_demand();assert_eq!(demand.copy_bytes,0);let grant=exact(demand);
   if !builder.is_initialized(){for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let before=builder.is_initialized();let(answer,heap)=observe(||caller.turn(denied,|cx|{let turn=builder.advance_initialization(cx);assert_eq!(turn.work,0);receive_original_retained_work(cx,turn)}));assert_eq!(answer.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(caller.receipt(),Default::default());assert_eq!(builder.is_initialized(),before);}}
   let(answer,heap)=observe(||caller.turn(grant,|cx|{let work=cx.original_work_units_spent();let outcome=builder.advance_initialization(cx);assert_eq!(outcome.work,u128::from(turn<turns));let step=receive_original_retained_work(cx,outcome)?;assert_eq!(cx.original_work_units_spent()-work,u128::from(turn<turns));Ok(step)}));assert!(matches!(answer.unwrap(),RetainedCloneStep::Complete(_)));assert_eq!(heap,(0,0));assert_eq!(caller.receipt(),RetainedCloneProgress{copied_items:usize::from(turn<turns),..Default::default()});assert_eq!(builder.original().unwrap().page_count(),row["livePages"].as_u64().unwrap()as usize);assert_eq!(builder.native_header_identity(),identity);
  }
  assert_eq!(builder.is_initialized(),cut>=turns);assert_eq!(builder.native_header_identity(),identity);
  if !builder.is_initialized(){let demand=builder.initialization_demand();let(answer,heap)=observe(||caller.turn(exact(demand),|cx|cx.with_original_work_loan(0,cx.deadline_us(),|cx|{let turn=builder.advance_initialization(cx);assert_eq!(turn.work,0);receive_original_retained_work(cx,turn)})));assert_eq!(answer.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(caller.receipt(),Default::default());assert!(!builder.is_initialized());caller.cancel().cancel_now();let(answer,heap)=observe(||caller.turn(exact(demand),|cx|{let turn=builder.advance_initialization(cx);assert_eq!(turn.work,0);receive_original_retained_work(cx,turn)}));assert_eq!(answer.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(caller.receipt(),Default::default());assert!(!builder.is_initialized());}
  while !builder.terminal_is_empty(){let demand=builder.retirement_demands().unwrap();let mut heap=(0,0);let answer=caller.turn(exact(demand),|cx|close_original_effect_step(cx,demand,|effect|{let(poll,inner)=semio_framework_value_testing_allocator::observe_retirement_allocations(||semio_framework_value_control_contract::RetainedWorkPoll::Complete(builder.close_step(effect)));heap=inner;poll}));let receipt=answer.unwrap().progress();assert_eq!(heap,(receipt.retained_capacity_bytes,receipt.released_bytes));assert_eq!(receipt.copied_bytes,demand.copy_bytes);}assert_eq!(observe(||unsafe{storage.assume_init_drop()}).1,(0,0));let(released,heap)=observe(||caller.retire(stock));assert_eq!(released,birth.0);assert_eq!(heap.1.checked_sub(heap.0),Some(birth.0));
 }
}
